// GENERATED by npm run sync-engine from packages/engine/src/match.ts. Do not edit.
import { applyMove, applyTimeout, createRound, DEFAULT_ROUND_CONFIG, isSuddenDeath, validateConfig } from './round.ts';
import { EngineError, other } from './types.ts';
import type { Player, RoundConfig, RoundEndReason, RoundState } from './types.ts';

export type TimeControl = 'blitz' | 'rapid';

export const TIME_CONTROLS: Record<TimeControl, { moveMs: number; suddenDeathMs: number }> = {
  blitz: { moveMs: 3000, suddenDeathMs: 1500 },
  rapid: { moveMs: 8000, suddenDeathMs: 4000 },
};

export const DEFAULT_TIME_CONTROL: TimeControl = 'rapid';

/** Online timing rules. Enforced by the server; the numbers live here with the other rules. */
export const MATCH_TIMING = {
  /** Match is aborted if a player makes no move in round 1 within this long of the start. */
  abortAfterMs: 15_000,
  /** A player disconnected this long in total during a round forfeits the match. */
  disconnectForfeitMs: 20_000,
  /**
   * Network grace added to every turn deadline. 800 ms, not the PRD's 250 ms: the server
   * is in Frankfurt and players are in India (BUILD_PLAN decision, 2026-11-02).
   */
  moveGraceMs: 800,
} as const;

/**
 * Round 1 starter is decided by a tap race: "GET READY… GO!", fastest tap starts.
 * Reaction times are measured on each device from when GO was shown.
 */
export const START_RACE = {
  /** Taps faster than this after GO count as anticipation, i.e. a false start. */
  minReactionMs: 100,
  /** Reactions this close together are a tie, settled by the coin. */
  tieMs: 10,
  /** No tap within this long after GO counts as no tap. */
  windowMs: 5000,
} as const;

export type RaceTap =
  | { kind: 'tap'; reactionMs: number }
  /** Tapped before GO. */
  | { kind: 'falseStart' }
  /** Didn't tap within START_RACE.windowMs. */
  | { kind: 'none' };

/**
 * Who starts round 1. `coin` (chosen at random by the caller) settles ties,
 * double false starts and double no-shows.
 */
export function resolveStartRace(x: RaceTap, o: RaceTap, coin: Player): Player {
  const rank = (t: RaceTap): number => {
    if (t.kind === 'falseStart') return Infinity;
    if (t.kind === 'none') return START_RACE.windowMs;
    if (t.reactionMs < START_RACE.minReactionMs) return Infinity;
    return Math.min(t.reactionMs, START_RACE.windowMs);
  };
  const rx = rank(x);
  const ro = rank(o);
  if (rx === ro || Math.abs(rx - ro) <= START_RACE.tieMs) return coin;
  return rx < ro ? 'X' : 'O';
}

export interface MatchConfig {
  round: RoundConfig;
  /** Best of this many rounds (odd). First to ceil(bestOf / 2) wins. */
  bestOf: number;
  timeControl: TimeControl;
}

export const DEFAULT_MATCH_CONFIG: MatchConfig = {
  round: DEFAULT_ROUND_CONFIG,
  bestOf: 5,
  timeControl: DEFAULT_TIME_CONTROL,
};

/** roundOver: a round just ended and the next one hasn't started (UI shows the result). */
export type MatchStatus = 'playing' | 'roundOver' | 'finished' | 'aborted';
export type MatchEndReason = 'rounds' | 'resign' | 'disconnect' | 'aborted';

export interface RoundRecord {
  roundNo: number;
  starter: Player;
  /** null for a drawn round. */
  winner: Player | null;
  reason: RoundEndReason;
  plies: number;
}

/** Plain JSON (stored in matches.state). */
export interface MatchState {
  config: MatchConfig;
  /** Who started round 1 (winner of the start race). */
  firstStarter: Player;
  roundNo: number;
  score: Record<Player, number>;
  history: RoundRecord[];
  /** The current round, or the round that just ended while status is roundOver/finished. */
  round: RoundState;
  status: MatchStatus;
  /** Match winner; null while playing, for a drawn match, or when aborted. */
  winner: Player | null;
  reason: MatchEndReason | null;
}

export function winsNeeded(config: MatchConfig): number {
  return Math.ceil(config.bestOf / 2);
}

/** Starter alternates every round, drawn rounds included. */
export function roundStarter(firstStarter: Player, roundNo: number): Player {
  return roundNo % 2 === 1 ? firstStarter : other(firstStarter);
}

/** `firstStarter` comes from resolveStartRace (the caller supplies the coin, so the engine stays deterministic). */
export function createMatch(config: MatchConfig, firstStarter: Player): MatchState {
  validateConfig(config.round);
  if (!Number.isInteger(config.bestOf) || config.bestOf < 1 || config.bestOf % 2 === 0) {
    throw new EngineError('bestOf must be a positive odd integer');
  }
  return {
    config: { ...config, round: { ...config.round } },
    firstStarter,
    roundNo: 1,
    score: { X: 0, O: 0 },
    history: [],
    round: createRound(config.round, firstStarter),
    status: 'playing',
    winner: null,
    reason: null,
  };
}

/** Clock for the current turn, in ms (sudden death after config.round.suddenDeathAfter plies). */
export function turnClockMs(match: MatchState): number {
  const tc = TIME_CONTROLS[match.config.timeControl];
  return isSuddenDeath(match.round) ? tc.suddenDeathMs : tc.moveMs;
}

function settleRound(match: MatchState, round: RoundState): MatchState {
  if (round.status === 'playing') return { ...match, round };
  const score = { ...match.score };
  if (round.winner) score[round.winner] += 1;
  const record: RoundRecord = {
    roundNo: match.roundNo,
    starter: round.starter,
    winner: round.winner,
    reason: round.reason!,
    plies: round.ply,
  };
  const next: MatchState = { ...match, round, score, history: [...match.history, record] };
  const need = winsNeeded(match.config);
  const remaining = match.config.bestOf - match.roundNo;
  const lead = score.X - score.O;
  if (score.X >= need || score.O >= need || remaining === 0 || Math.abs(lead) > remaining) {
    // Early clinch: once the trailing player can't even draw level, the match is over.
    next.status = 'finished';
    next.reason = 'rounds';
    next.winner = lead > 0 ? 'X' : lead < 0 ? 'O' : null;
  } else {
    next.status = 'roundOver';
  }
  return next;
}

function assertPlaying(match: MatchState): void {
  if (match.status !== 'playing') throw new EngineError(`match is ${match.status}`);
}

export function matchMove(match: MatchState, cell: number): MatchState {
  assertPlaying(match);
  return settleRound(match, applyMove(match.round, cell));
}

export function matchTimeout(match: MatchState): MatchState {
  assertPlaying(match);
  return settleRound(match, applyTimeout(match.round));
}

export function startNextRound(match: MatchState): MatchState {
  if (match.status !== 'roundOver') throw new EngineError('no round to start');
  const roundNo = match.roundNo + 1;
  return {
    ...match,
    roundNo,
    round: createRound(match.config.round, roundStarter(match.firstStarter, roundNo)),
    status: 'playing',
  };
}

function endMatch(match: MatchState, loser: Player, reason: 'resign' | 'disconnect'): MatchState {
  if (match.status === 'finished' || match.status === 'aborted') {
    throw new EngineError(`match is ${match.status}`);
  }
  return { ...match, status: 'finished', winner: other(loser), reason };
}

/** Resigning is allowed any time before the match ends, and loses the match. */
export function resign(match: MatchState, player: Player): MatchState {
  return endMatch(match, player, 'resign');
}

/** Player was disconnected too long (MATCH_TIMING.disconnectForfeitMs) and loses the match. */
export function forfeitDisconnect(match: MatchState, player: Player): MatchState {
  return endMatch(match, player, 'disconnect');
}

/** True while an abort is still possible: round 1 and `player` hasn't placed a mark yet. */
export function canAbort(match: MatchState, player: Player): boolean {
  if (match.status !== 'playing' || match.roundNo !== 1) return false;
  return !hasPlacedThisRound(match.round, player);
}

function hasPlacedThisRound(round: RoundState, player: Player): boolean {
  // A player who never placed has timed out on every one of their turns, and the
  // consecutive counter only resets on a placement, so turns taken === timeouts.
  const turnsTaken = round.starter === player ? Math.ceil(round.ply / 2) : Math.floor(round.ply / 2);
  return turnsTaken > round.timeouts[player];
}

/** Abort (no rating change). Server decides when, using MATCH_TIMING.abortAfterMs and canAbort. */
export function abortMatch(match: MatchState): MatchState {
  if (match.status === 'finished' || match.status === 'aborted') {
    throw new EngineError(`match is ${match.status}`);
  }
  return { ...match, status: 'aborted', winner: null, reason: 'aborted' };
}
